return function(ui,frame,checkPlanningSearch)
	frame("map-delirium-imported");ui:click("delirium");assert(main.popups[1].controls.current.buf=="35");frame("map-delirium-projection");ui:click("chooseOrb");ui:text("search","Fine Delirium Orb");frame("map-delirium-orb-picker");ui:click("choose")
	assert(main.popups[1].controls.nextType.buf=="Currency Items","Orb picker did not choose the client reward type");local projectionText="";for _,row in ipairs(main.popups[1].controls.results.list) do projectionText=projectionText..StripEscapes(row[1] or "").." " end;assert(projectionText:find("45%",1,true),"Equivalent reward labels did not stack");ui:text("target","80");projectionText="";for _,row in ipairs(main.popups[1].controls.results.list) do projectionText=projectionText..StripEscapes(row[1] or "").." " end;assert(projectionText:gsub("%s+"," "):find("Target 80%: 1-9 orbs",1,true),"Delirium target bounds were not shown");frame("map-delirium-orb-selected");ui:click("keepPlan");local plannedText="";for _,row in ipairs(main.popups[1].controls.affixes.list) do plannedText=plannedText..StripEscapes(row[1] or "").." " end;assert(plannedText:find("Planned Delirium",1,true),"Saved target was not marked as hypothetical");frame("map-delirium-kept-plan");ui:click("delirium");assert(main.popups[1].controls.target.buf=="80","Saved target did not reopen");checkPlanningSearch(ui,nil,"delirium");ui:text("nextType","Imaginary reward");projectionText="";for _,row in ipairs(main.popups[1].controls.results.list) do projectionText=projectionText..StripEscapes(row[1] or "").." " end;assert(projectionText:find("Unrecognized next reward type",1,true),"Unknown reward did not explain why it cannot be projected");ui:text("nextType","Maps");ui:click("clearPlan");ui:choose("tier",16,"val")
end
